import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useTheme } from '../../context/ThemeContext';
import { FiMenu, FiX, FiSun, FiMoon, FiUser, FiLogOut, FiBook, FiHome, FiInfo, FiMessageSquare } from 'react-icons/fi';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '../ui';

const Navbar = () => {
  const { currentUser, isAuthenticated, logout, isAdmin, isTeacher, isStudent } = useAuth();
  const { darkMode, toggleDarkMode } = useTheme();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  // Check if the current path matches the link
  const isActive = (path) => {
    return location.pathname === path;
  };

  // Handle scroll effect
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 10) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const toggleProfile = () => {
    setIsProfileOpen(!isProfileOpen);
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  // Define dashboard link based on user role
  const getDashboardLink = () => {
    if (isAdmin) return '/dashboard/admin';
    if (isTeacher) return '/dashboard/teacher';
    if (isStudent) return '/dashboard/student';
    return '/dashboard';
  };

  const navItemsData = [
    { path: '/', label: 'الرئيسية', icon: <FiHome /> },
    { path: '/courses', label: 'الدورات', icon: <FiBook /> },
    { path: '/about', label: 'من نحن', icon: <FiInfo /> },
    { path: '/contact', label: 'اتصل بنا', icon: <FiMessageSquare /> },
  ];

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${isScrolled ? 'bg-white/95 dark:bg-[#1a1a1a]/95 backdrop-blur-sm shadow-md' : 'bg-transparent dark:bg-transparent'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16 md:h-20 items-center">
          <div className="flex-shrink-0 flex items-center">
            <Link to="/" className="flex items-center gap-2">
              <div className="w-10 h-10 bg-primary rounded-lg flex items-center justify-center shadow-lg">
                <span className="text-white text-lg font-bold">ت</span>
              </div>
              <span className={`text-xl md:text-2xl font-title font-bold ${isScrolled ? 'text-primary dark:text-primary-400' : 'text-primary dark:text-[#f2f2f2]'}`}>
                المنصة التعليمية العربية
              </span>
            </Link>
          </div>

          {/* Desktop Menu */}
          <div className="hidden md:flex items-center space-x-1 space-x-reverse">
            <div className="flex space-x-1 space-x-reverse">
              {navItemsData.map((item) => (
                <Link 
                  key={item.path} 
                  to={item.path}
                  className={`nav-link flex items-center gap-1.5 ${isActive(item.path) ? 'nav-link-active' : ''}`}
                >
                  {item.icon}
                  <span>{item.label}</span>
                </Link>
              ))}
            </div>

            <div className="mr-8 flex items-center space-x-2 space-x-reverse">
              {/* Theme Toggle */}
              <motion.button
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={toggleDarkMode}
                className={`p-2 rounded-full ${isScrolled 
                  ? 'bg-gray-100 dark:bg-[#333333] text-primary dark:text-primary-400' 
                  : 'bg-white/10 text-white dark:text-[#f2f2f2] backdrop-blur-sm'
                } focus:outline-none transition-colors duration-300`}
                aria-label="Toggle dark mode"
              >
                {darkMode ? <FiSun className="h-5 w-5" /> : <FiMoon className="h-5 w-5" />}
              </motion.button>

              {/* Auth Buttons */}
              {isAuthenticated ? (
                <div className="relative">
                  <motion.button
                    whileHover={{ scale: 1.03 }}
                    whileTap={{ scale: 0.97 }}
                    onClick={toggleProfile}
                    className={`flex items-center gap-2 px-3 py-2 rounded-xl ${isScrolled 
                      ? 'bg-gray-100 dark:bg-[#333333] text-text-primary dark:text-[#f2f2f2]' 
                      : 'bg-white/10 text-white dark:text-[#f2f2f2] backdrop-blur-sm'
                    } transition-colors duration-300`}
                  >
                    <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white font-semibold">
                      {currentUser?.name ? currentUser.name.charAt(0).toUpperCase() : <FiUser />}
                    </div>
                    <span className="text-sm font-medium">{currentUser?.name}</span>
                  </motion.button>

                  <AnimatePresence>
                    {isProfileOpen && (
                      <motion.div
                        initial={{ opacity: 0, y: 5, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 5, scale: 0.95 }}
                        transition={{ duration: 0.2 }}
                        className="absolute left-0 mt-2 w-56 bg-white dark:bg-gray-800 rounded-xl shadow-xl py-2 z-10 border border-gray-100 dark:border-gray-700"
                      >
                        <div className="px-4 py-3 border-b border-gray-100 dark:border-gray-700">
                          <p className="text-sm font-medium text-text-primary dark:text-white">{currentUser?.name}</p>
                          <p className="text-xs text-text-secondary dark:text-gray-400 mt-1">{currentUser?.email}</p>
                        </div>
                        <Link
                          to={getDashboardLink()}
                          className="flex items-center gap-2 px-4 py-2.5 text-sm text-text-primary dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700 w-full text-right"
                          onClick={() => setIsProfileOpen(false)}
                        >
                          <FiUser className="h-4 w-4" />
                          <span>لوحة التحكم</span>
                        </Link>
                        <div className="border-t border-gray-100 dark:border-gray-700 my-1"></div>
                        <button
                          onClick={handleLogout}
                          className="flex items-center gap-2 px-4 py-2.5 text-sm text-error hover:bg-red-50 dark:hover:bg-red-900/20 w-full text-right"
                        >
                          <FiLogOut className="h-4 w-4" />
                          <span>تسجيل الخروج</span>
                        </button>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              ) : (
                <div className="flex space-x-2 space-x-reverse">
                  <Button 
                    as={Link} 
                    to="/login" 
                    variant="outline"
                    size="sm"
                    className={isScrolled ? '' : 'border-white/70 text-white hover:bg-white/10 dark:border-white/70 dark:text-white'}
                  >
                    تسجيل الدخول
                  </Button>
                  <Button 
                    as={Link} 
                    to="/register/student" 
                    variant="accent"
                    size="sm"
                    className="shadow-md"
                  >
                    التسجيل
                  </Button>
                </div>
              )}
            </div>
          </div>

          {/* Mobile Menu Button */}
          <div className="flex md:hidden items-center gap-2">
            {/* Theme Toggle */}
            <motion.button
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={toggleDarkMode}
              className={`p-2 rounded-full ${isScrolled 
                ? 'bg-gray-100 dark:bg-[#333333] text-primary dark:text-primary-400' 
                : 'bg-white/10 text-white dark:text-[#f2f2f2] backdrop-blur-sm'
              } focus:outline-none transition-colors duration-300`}
              aria-label="Toggle dark mode"
            >
              {darkMode ? <FiSun className="h-5 w-5" /> : <FiMoon className="h-5 w-5" />}
            </motion.button>

            <button
              onClick={toggleMenu}
              className={`p-2 rounded-lg ${isScrolled 
                ? 'text-text-primary dark:text-white' 
                : 'text-white dark:text-white'
              } focus:outline-none transition-colors duration-300`}
              aria-expanded={isMenuOpen}
            >
              {isMenuOpen ? <FiX className="h-6 w-6" /> : <FiMenu className="h-6 w-6" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {isMenuOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.3 }}
            className="md:hidden bg-white dark:bg-gray-900 shadow-lg rounded-b-xl overflow-hidden"
          >
            <div className="px-4 py-5 space-y-3 max-h-[calc(100vh-5rem)] overflow-y-auto">
              {navItemsData.map((item) => (
                <Link 
                  key={item.path}
                  to={item.path}
                  className={`flex items-center gap-3 p-3 rounded-xl text-base font-medium ${
                    isActive(item.path)
                      ? 'bg-primary-50 dark:bg-gray-800 text-primary dark:text-primary-400'
                      : 'text-text-primary dark:text-white hover:bg-gray-50 dark:hover:bg-gray-800'
                  }`}
                  onClick={() => setIsMenuOpen(false)}
                >
                  <div className="text-xl">{item.icon}</div>
                  <span>{item.label}</span>
                </Link>
              ))}

              <div className="border-t border-gray-100 dark:border-gray-800 my-2 pt-2">
                {isAuthenticated ? (
                  <>
                    <div className="flex items-center gap-3 p-3 mb-2">
                      <div className="w-10 h-10 rounded-full bg-primary flex items-center justify-center text-white font-semibold">
                        {currentUser?.name ? currentUser.name.charAt(0).toUpperCase() : <FiUser />}
                      </div>
                      <div>
                        <p className="font-medium text-text-primary dark:text-white">{currentUser?.name}</p>
                        <p className="text-xs text-text-secondary dark:text-gray-400">{currentUser?.email}</p>
                      </div>
                    </div>
                    <Link
                      to={getDashboardLink()}
                      className="flex items-center gap-3 p-3 rounded-xl text-base font-medium text-text-primary dark:text-white hover:bg-gray-50 dark:hover:bg-gray-800"
                      onClick={() => setIsMenuOpen(false)}
                    >
                      <FiUser className="text-xl" />
                      <span>لوحة التحكم</span>
                    </Link>
                    <button
                      onClick={() => {
                        handleLogout();
                        setIsMenuOpen(false);
                      }}
                      className="w-full flex items-center gap-3 p-3 rounded-xl text-base font-medium text-error hover:bg-red-50 dark:hover:bg-red-900/20"
                    >
                      <FiLogOut className="text-xl" />
                      <span>تسجيل الخروج</span>
                    </button>
                  </>
                ) : (
                  <div className="grid grid-cols-2 gap-3 mt-4">
                    <Button 
                      as={Link} 
                      to="/login" 
                      variant="outline"
                      className="w-full"
                      onClick={() => setIsMenuOpen(false)}
                    >
                      تسجيل الدخول
                    </Button>
                    <Button 
                      as={Link} 
                      to="/register/student" 
                      variant="accent"
                      className="w-full"
                      onClick={() => setIsMenuOpen(false)}
                    >
                      التسجيل
                    </Button>
                  </div>
                )}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
};

export default Navbar;
